<?php
require 'config/auth.php';require 'config/db.php';require 'config/reporting_35.php';require_permission('voucher.pay');
$id=(int)($_GET['id']??0);$q=$conn->prepare('SELECT * FROM control_accounts WHERE id=? AND cancelled_at IS NULL');$q->bind_param('i',$id);$q->execute();$account=$q->get_result()->fetch_assoc();if(!$account||!can_access_unit((int)$account['unit_id'])){http_response_code(403);exit('ไม่พบบัญชีที่มีสิทธิ์ยืนยัน');}
$error='';$ready=organization_ready($conn);
if($_SERVER['REQUEST_METHOD']==='POST')try{if(!$ready)throw new DomainException('ต้องติดตั้ง migration v8 ก่อน');begin_financial_transaction($conn);$entry=(int)($_POST['entry_id']??0);$q=$conn->prepare('SELECT control_account_id FROM control_account_entries WHERE id=?');$q->bind_param('i',$entry);$q->execute();$row=$q->get_result()->fetch_assoc();if(!$row||(int)$row['control_account_id']!==$id)throw new DomainException('รายการไม่ตรงกับบัญชีคุมงบประมาณนี้');$action=$_POST['action']??'confirm';if($action==='confirm')report_gfmis_confirm($conn,$entry,$_POST);elseif(in_array($action,['edit','cancel'],true))report_gfmis_edit($conn,$entry,$_POST,$action==='cancel');else throw new DomainException('ไม่พบคำสั่ง');$conn->commit();header('Location: gfmis_confirm.php?id='.$id.'&saved=1');exit;}catch(Throwable $e){$conn->rollback();$error=operation_error($e);}
$rows=[];if($ready){$q=$conn->prepare("SELECT e.*,g.confirmed_amount,g.confirmed_date,g.reference_no FROM control_account_entries e LEFT JOIN gfmis_payment_confirmations g ON g.ledger_entry_id=e.id WHERE e.control_account_id=? AND e.entry_type='payment' AND e.voided_at IS NULL ORDER BY e.entry_date,e.id");$q->bind_param('i',$id);$q->execute();$rows=$q->get_result()->fetch_all(MYSQLI_ASSOC);}
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ยืนยันผลเบิก GFMIS | 35MDBS</title><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"></head><body><?php require 'template/nav.php';?><main class="container"><section class="panel"><h1 class="page-title">ยืนยันผลเบิก GFMIS · <?=htmlspecialchars($account['budget_code'])?></h1><p>ใช้ยอดและวันที่จากหลักฐาน GFMIS จริง ไม่บันทึกตัดจ่ายซ้ำ แก้ไขหรือลบยอดยืนยันได้พร้อมเหตุผล โดยเก็บประวัติและไม่ตัดจ่ายซ้ำ</p><a class="btn btn-outline" href="control_account_detail.php?id=<?=$id?>">กลับบัญชีคุม</a></section><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert alert-success">ยืนยันยอด GF แล้ว</div><?php endif;?><?php foreach($rows as $r):?><section class="panel"><h2><?=htmlspecialchars($r['entry_date'].' · '.$r['note'])?></h2><p>ตัดจ่าย <?=number_format((float)$r['amount'],2)?> บาท</p><?php if($r['confirmed_amount']!==null):?><p>ยืนยัน GF <?=number_format((float)$r['confirmed_amount'],2)?> บาท · <?=htmlspecialchars($r['confirmed_date'].' · '.$r['reference_no'])?></p><details><summary>แก้ไขยอดยืนยัน</summary><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="edit"><input type="hidden" name="entry_id" value="<?=(int)$r['id']?>"><div class="field-grid"><div class="form-field"><label>วันที่ยืนยัน</label><input type="date" name="confirmed_date" value="<?=htmlspecialchars($r['confirmed_date'])?>" required></div><div class="form-field"><label>ยอดยืนยัน</label><input type="number" name="confirmed_amount" step="0.01" min="0.01" max="<?=htmlspecialchars($r['amount'])?>" value="<?=htmlspecialchars($r['confirmed_amount'])?>" required></div><div class="form-field"><label>เลขอ้างอิง</label><input name="reference_no" maxlength="100" value="<?=htmlspecialchars($r['reference_no'])?>" required></div><div class="form-field"><label>เหตุผลแก้ไข</label><input name="reason" minlength="5" maxlength="255" required></div></div><button class="btn btn-success">บันทึกการแก้ไข</button></form></details><details><summary>ลบยอดยืนยัน</summary><form method="post" onsubmit="return confirm('ยืนยันลบยอดยืนยัน GF? ยอดตัดจ่ายเดิมยังคงอยู่')"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="entry_id" value="<?=(int)$r['id']?>"><input name="reason" minlength="5" maxlength="255" placeholder="เหตุผลลบยอดยืนยัน" required><button class="btn btn-danger">ยืนยันลบยอดยืนยัน</button></form></details><?php else:?><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="entry_id" value="<?=(int)$r['id']?>"><div class="form-grid form-grid-2"><label>วันที่เบิก GF จริง</label><input type="date" name="confirmed_date" required><label>ยอดที่ยืนยัน</label><input type="number" name="confirmed_amount" step="0.01" min="0.01" max="<?=htmlspecialchars($r['amount'])?>" required><label>เลขอ้างอิง GFMIS</label><input name="reference_no" maxlength="100" required></div><button class="btn btn-primary">ยืนยันตามหลักฐาน</button></form><?php endif;?></section><?php endforeach;?><?php if(!$rows):?><section class="panel">ยังไม่มีรายการตัดจ่ายที่ยืนยันได้ หรือยังไม่ได้ติดตั้งตาราง v8</section><?php endif;?></main></body></html>
